//! The `@generated` header every generated file starts with, and writing or checking such a file.
//!
//! ```text
//! // @generated by `cargo xtask <task>` from <origin>; do not edit.
//! // input <path> blake3 <hex>
//! // output blake3 <hex>
//! ```
//!
//! One `input` line per file the generator read (its path in the origin), then the hash of everything after the
//! header. rustfmt leaves a file with `@generated` in its first lines alone, and the module that includes it carries
//! `#[rustfmt::skip]` as well, so the text stays as the generator wrote it.
use std::fs;
use std::path::Path;

const OUTPUT: &str = "// output blake3 ";

/// The file: the header naming `task`, `origin` and `inputs` (path, contents), then `body`.
pub(crate) fn file(task: &str, origin: &str, inputs: &[(&str, &[u8])], body: &str) -> String {
    let mut text = format!("// @generated by `cargo xtask {task}` from {origin}; do not edit.\n");
    for (path, contents) in inputs {
        text.push_str(&format!("// input {path} blake3 {}\n", blake3::hash(contents)));
    }
    text.push_str(&format!("{OUTPUT}{}\n", blake3::hash(body.as_bytes())));
    text.push_str(body);
    text
}

/// Whether `text` is a generated file whose body is the one its header records (the tests of each generator check
/// the committed file with it).
#[cfg(test)]
pub(crate) fn verify(text: &str) -> Result<(), String> {
    if !text.starts_with("// @generated by ") {
        return Err("it does not start with the `@generated` header".into());
    }
    let at = text.find(OUTPUT).ok_or("its header has no `output` line")?;
    let line = &text[at + OUTPUT.len()..];
    let end = line.find('\n').ok_or("its header's `output` line does not end")?;
    let (recorded, body) = (&line[..end], &line[end + 1..]);
    let actual = blake3::hash(body.as_bytes()).to_hex();
    if recorded != actual.as_str() {
        return Err(format!(
            "its body hashes to {actual}, its header records {recorded}: it was edited by hand"
        ));
    }
    Ok(())
}

/// Write `text` to `path`, or with `check`, compare it with the file there and fail where they differ.
pub(crate) fn write_or_check(path: &Path, text: &str, check: bool) -> Result<(), String> {
    if check {
        let committed = fs::read_to_string(path).map_err(|e| format!("{}: {e}", path.display()))?;
        if committed != text {
            return Err(format!(
                "{} differs from what its generator writes now",
                path.display()
            ));
        }
        return Ok(());
    }
    fs::write(path, text).map_err(|e| format!("{}: {e}", path.display()))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_file_verifies_until_its_body_changes() {
        let text = file("t", "o", &[("a/b.h", b"x")], "body\n");
        assert_eq!(verify(&text), Ok(()));
        assert!(
            verify(&text.replace("body", "bodY"))
                .unwrap_err()
                .contains("by hand")
        );
        assert!(verify("body\n").is_err());
    }
}
